begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
select no_plan();

select is((select count(*) from public.research_incident_transition_rules),81::bigint,'Incident matrix contains 81/81 pairs');
select is((select count(*) from public.research_incident_transition_rules where decision='ALLOWED'),25::bigint,'Incident matrix contains exactly 25 allowed pairs');
select is((select count(*) from public.research_incident_transition_rules where decision='PROHIBITED_INVALID'),56::bigint,'Incident matrix contains exactly 56 prohibited/invalid pairs');
select is((select count(distinct (current_status,requested_status)) from public.research_incident_transition_rules),81::bigint,'Incident matrix has no wildcard or implied pairs');
select is((select decision from public.research_incident_transition_rules where current_status='REPORTED' and requested_status='RESOLVED'),'PROHIBITED_INVALID','REPORTED to RESOLVED is prohibited');
select is((select decision from public.research_incident_transition_rules where current_status='RESOLVED' and requested_status='CLOSED'),'ALLOWED','RESOLVED to CLOSED is explicitly allowed');
select is((select count(*) from public.research_incident_transition_rules where current_status='CLOSED' and decision='ALLOWED'),0::bigint,'CLOSED has no outgoing transition');

select ok(to_regclass(name) is not null,name||' exists') from unnest(array[
 'public.research_incidents','public.research_incident_status_events','public.research_incident_gate_effects','public.research_incident_invalid_transition_attempts','public.research_incident_reviews','public.research_audit_integrity_assessments','public.research_fsh_collections','public.research_fsh_collection_members','public.research_fsh_results','public.research_fsh_result_supersession_events','public.research_release_gate_assessments']) name;
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid=name::regclass),name||' forces RLS') from unnest(array['public.research_incidents','public.research_incident_status_events','public.research_incident_gate_effects','public.research_fsh_results','public.research_release_gate_assessments']) name;
select ok(not has_table_privilege(role_name,'public.research_incidents','SELECT'),role_name||' cannot directly read Incidents') from unnest(array['anon','authenticated','service_role']) role_name;
select ok(not has_table_privilege(role_name,'public.research_fsh_results','INSERT'),role_name||' cannot directly insert FSH') from unnest(array['anon','authenticated','service_role']) role_name;
select ok(to_regprocedure(name) is not null,name||' exists') from unnest(array[
 'public.report_research_incident(uuid,uuid,text,text,timestamptz,text,text,jsonb,text[],text,boolean,uuid)',
 'public.transition_research_incident(uuid,uuid,text,text[],jsonb,uuid)',
 'public.restore_research_incident_gate(uuid,text,uuid,jsonb,text,uuid)',
 'public.create_successor_research_incident(uuid,uuid,boolean,timestamptz,jsonb,uuid)',
 'public.execute_synthetic_governed_fsh(uuid,uuid,jsonb,uuid)',
 'public.evaluate_wave3_release_gate(text,uuid,uuid)',
 'public.assess_research_audit_completeness(uuid,uuid,text,text[],uuid,boolean,uuid)',
 'public.get_admin_research_wave3_overview(uuid,uuid,uuid)']) name;
select ok((select prosecdef and proconfig @> array['search_path=public, pg_catalog'] from pg_proc where oid=to_regprocedure(name)),name||' is a fixed-search-path security definer') from unnest(array[
 'public.report_research_incident(uuid,uuid,text,text,timestamptz,text,text,jsonb,text[],text,boolean,uuid)',
 'public.transition_research_incident(uuid,uuid,text,text[],jsonb,uuid)',
 'public.execute_synthetic_governed_fsh(uuid,uuid,jsonb,uuid)',
 'public.evaluate_wave3_release_gate(text,uuid,uuid)']) name;

insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
('00000000-0000-0000-0000-000000000000','c1000000-0000-4000-8000-000000000001','authenticated','authenticated','admin52@test.local','','2026-01-01','{"provider":"email","providers":["email"]}','{}','2026-01-01','2026-01-01'),
('00000000-0000-0000-0000-000000000000','c1000000-0000-4000-8000-000000000002','authenticated','authenticated','admin52b@test.local','','2026-01-01','{"provider":"email","providers":["email"]}','{}','2026-01-01','2026-01-01'),
('00000000-0000-0000-0000-000000000000','c1000000-0000-4000-8000-000000000003','authenticated','authenticated','reviewer52@test.local','','2026-01-01','{"provider":"email","providers":["email"]}','{}','2026-01-01','2026-01-01'),
('00000000-0000-0000-0000-000000000000','c1000000-0000-4000-8000-000000000011','authenticated','authenticated','participant52@test.local','','2026-01-01','{"provider":"email","providers":["email"]}','{}','2026-01-01','2026-01-01');
insert into public.staff_members(id,auth_user_id,staff_code,full_name,email,status,created_at) values
('c2000000-0000-4000-8000-000000000001','c1000000-0000-4000-8000-000000000001','WPAG-STF-952001','Wave 3 Admin','admin52@test.local','active','2026-01-01'),
('c2000000-0000-4000-8000-000000000002','c1000000-0000-4000-8000-000000000002','WPAG-STF-952002','Wave 3 Admin B','admin52b@test.local','active','2026-01-01'),
('c2000000-0000-4000-8000-000000000003','c1000000-0000-4000-8000-000000000003','WPAG-STF-952003','Wave 3 Reviewer','reviewer52@test.local','active','2026-01-01');
insert into public.staff_member_roles(staff_member_id,staff_role_id,is_active,assigned_at)
select s.id,r.id,true,'2026-01-01' from public.staff_members s join public.staff_roles r on r.role_code=case when s.id='c2000000-0000-4000-8000-000000000003' then 'reviewer' else 'administrator' end where s.id::text like 'c2000000%';
insert into public.participants(id,auth_user_id,participant_code,lifecycle_status,created_at) values('c3000000-0000-4000-8000-000000000001','c1000000-0000-4000-8000-000000000011','WPAG-952001','active','2026-01-01');

create temporary table w3(key text primary key,value uuid not null);
insert into w3 select 'enrollment',enrollment_id from public.create_or_get_research_enrollment('c3000000-0000-4000-8000-000000000001','c1000000-0000-4000-8000-000000000001','FSH Phase 1','PUR-01','Protocol-v1','Consent-v0.2','Privacy-v0.1','Lifecycle-v0.2','Evidence-v0.1','synthetic_test','c9000000-0000-4000-8000-000000000001');
select lives_ok(format($q$select * from public.record_research_consent_transition(%L,'c1000000-0000-4000-8000-000000000001','PRESENTED','Consent-v1',repeat('a',64),'Protocol-v1','{"FSH":"FSH-PLAN-v1"}',array['FSH'],array['BASELINE_RESEARCH','FOLLOW_UP_RESEARCH'],true,'en-v1','INTERNAL_SYNTHETIC','{}','PRESENT','c9000000-0000-4000-8000-000000000002')$q$,(select value from w3 where key='enrollment')),'synthetic consent presented');
select lives_ok(format($q$select * from public.record_research_consent_transition(%L,'c1000000-0000-4000-8000-000000000011','GRANTED','Consent-v1',repeat('a',64),'Protocol-v1','{"FSH":"FSH-PLAN-v1"}',array['FSH'],array['BASELINE_RESEARCH','FOLLOW_UP_RESEARCH'],true,'en-v1','INTERNAL_SYNTHETIC','{"affirmative":true}','GRANT','c9000000-0000-4000-8000-000000000003')$q$,(select value from w3 where key='enrollment')),'synthetic consent granted');
select lives_ok(format($q$select * from public.record_research_privacy_binding(%L,'c1000000-0000-4000-8000-000000000001','PUR-01',array['RESEARCH_IDENTITY','FINANCIAL_EVIDENCE','RESEARCH_EVENT','ADJUDICATED_OUTCOME','AUDIT_PROVENANCE'],'STANDARD_RESTRICTED','RESTRICTED_RESEARCH','PURPOSE_SCOPED','RC-01','ACTIVE_RETAIN','NO_EXTERNAL_SHARING','NOT_AUTHORIZED','NONE',true,true,true,true,false,false,'SYNTHETIC_OPEN','c9000000-0000-4000-8000-000000000004')$q$,(select value from w3 where key='enrollment')),'synthetic privacy gate opened');

-- FSH exact governed chain.
insert into w3 select 'load1',evidence_version_id from public.create_synthetic_research_evidence((select value from w3 where key='enrollment'),null,'FSH','c1000000-0000-4000-8000-000000000001','PUR-01','FSH-LOAD-1','SYSTEM_RECORDED','2026-08-01','2026-08-01','PRESENT','{"value":100.2500,"operand_identity":"FSH-OP-LOAD-CURRENT-AMOUNT-v0.1","canonical_membership_identity":"LOAD-A","currency":"INR","unit":"MONTHLY_CURRENCY_AMOUNT","period_start":"2026-08-01","period_end":"2026-08-31","mechanics_state":"ELIGIBLE","authority_state":"RESOLVED","current_status":"CURRENT","collection_complete":true}','{"synthetic":true}',null,null,'c9000000-0000-4000-8000-000000000005');
insert into w3 select 'evaluation',i.evaluation_id from public.research_evidence_items i join public.research_evidence_versions v on v.evidence_item_id=i.id where v.id=(select value from w3 where key='load1');
insert into w3 select 'flow1',evidence_version_id from public.create_synthetic_research_evidence((select value from w3 where key='enrollment'),(select value from w3 where key='evaluation'),'FSH','c1000000-0000-4000-8000-000000000001','PUR-01','FSH-FLOW-1','SYSTEM_RECORDED','2026-08-01','2026-08-01','PRESENT','{"value":150.7500,"operand_identity":"FSH-OP-FLOW-CURRENT-AMOUNT-v0.1","canonical_membership_identity":"FLOW-A","currency":"INR","unit":"MONTHLY_CURRENCY_AMOUNT","period_start":"2026-08-01","period_end":"2026-08-31","mechanics_state":"ELIGIBLE","authority_state":"RESOLVED","current_status":"CURRENT","collection_complete":true}','{"synthetic":true}',null,null,'c9000000-0000-4000-8000-000000000006');
insert into w3 values('snapshot1',public.freeze_synthetic_research_snapshot((select value from w3 where key='enrollment'),'FSH','c1000000-0000-4000-8000-000000000001','BASELINE',null,array[(select value from w3 where key='load1'),(select value from w3 where key='flow1')],'COMPLETE','CURRENT','c9000000-0000-4000-8000-000000000007'));
create temporary table fsh1 as select * from public.execute_synthetic_governed_fsh((select value from w3 where key='snapshot1'),'c1000000-0000-4000-8000-000000000001','{"capacity_qualification":"ELIGIBLE_METADATA_ONLY"}','c9000000-0000-4000-8000-000000000008');
insert into w3 select 'result1',result_id from fsh1;
select is((select load_total from fsh1),'100.2500','one eligible LOAD is preserved exactly');
select is((select flow_total from fsh1),'150.7500','one eligible FLOW is preserved exactly');
select is((select fsh_value from fsh1),'50.5000','FSH equals exact FLOW minus LOAD');
select is((select load_component from public.research_fsh_results where id=(select value from w3 where key='result1')),100.2500::numeric,'LOAD_COMPONENT equals LOAD_TOTAL');
select is((select flow_component from public.research_fsh_results where id=(select value from w3 where key='result1')),150.7500::numeric,'FLOW_COMPONENT equals FLOW_TOTAL');
select is((select system_state_status from fsh1),'NOT_AUTHORIZED','positive FSH does not infer State');
select is((select participant_release_status from fsh1),'BLOCKED','FSH remains participant suppressed');
select matches((select result_sha256 from public.research_fsh_results where id=(select value from w3 where key='result1')),'^[0-9a-f]{64}$','FSH result has deterministic checksum identity');
select is((select count(*) from public.research_fsh_collections where snapshot_id=(select value from w3 where key='snapshot1')),2::bigint,'LOAD and FLOW collections are separate');
select is((select count(*) from public.research_fsh_collection_members where collection_id in (select id from public.research_fsh_collections where snapshot_id=(select value from w3 where key='snapshot1'))),2::bigint,'complete canonical collection membership is preserved');
select throws_ok(format($q$select * from public.execute_synthetic_governed_fsh(%L,'c1000000-0000-4000-8000-000000000001','{"numeric_cap":1}','c9000000-0000-4000-8000-000000000009')$q$,(select value from w3 where key='snapshot1')),'P1001','CAP is non-numerical qualification metadata only.','CAP cannot be a numerical operand');
select throws_ok(format($q$update public.research_fsh_results set fsh_value=0 where id=%L$q$,(select value from w3 where key='result1')),'P1001','Research Wave 3 records are append-only.','FSH result is immutable');
select is((select count(*) from public.research_fsh_results where system_state_status<>'NOT_AUTHORIZED'),0::bigint,'no final System State exists');
select is((select count(*) from public.research_fsh_results where participant_release_status<>'BLOCKED'),0::bigint,'no FSH participant release exists');

-- Successor snapshot creates successor result, never overwrites prior.
insert into w3 values('load2',public.correct_synthetic_research_evidence_version((select value from w3 where key='load1'),'c1000000-0000-4000-8000-000000000001','PRESENT','{"value":110.2500,"operand_identity":"FSH-OP-LOAD-CURRENT-AMOUNT-v0.1","canonical_membership_identity":"LOAD-A","currency":"INR","unit":"MONTHLY_CURRENCY_AMOUNT","period_start":"2026-08-01","period_end":"2026-08-31","mechanics_state":"ELIGIBLE","authority_state":"RESOLVED","current_status":"CURRENT","collection_complete":true}','SYNTHETIC_SUCCESSOR','c9000000-0000-4000-8000-000000000010'));
insert into w3 values('flow2',public.correct_synthetic_research_evidence_version((select value from w3 where key='flow1'),'c1000000-0000-4000-8000-000000000001','PRESENT','{"value":140.7500,"operand_identity":"FSH-OP-FLOW-CURRENT-AMOUNT-v0.1","canonical_membership_identity":"FLOW-A","currency":"INR","unit":"MONTHLY_CURRENCY_AMOUNT","period_start":"2026-08-01","period_end":"2026-08-31","mechanics_state":"ELIGIBLE","authority_state":"RESOLVED","current_status":"CURRENT","collection_complete":true}','SYNTHETIC_SUCCESSOR','c9000000-0000-4000-8000-000000000011'));
insert into w3 select 'load_extra',evidence_version_id from public.create_synthetic_research_evidence((select value from w3 where key='enrollment'),(select value from w3 where key='evaluation'),'FSH','c1000000-0000-4000-8000-000000000001','PUR-01','FSH-LOAD-EXTRA','SYSTEM_RECORDED','2026-08-01','2026-08-01','PRESENT','{"value":20.0000,"operand_identity":"FSH-OP-LOAD-CURRENT-AMOUNT-v0.1","canonical_membership_identity":"LOAD-B","currency":"INR","unit":"MONTHLY_CURRENCY_AMOUNT","period_start":"2026-08-01","period_end":"2026-08-31","mechanics_state":"ELIGIBLE","authority_state":"RESOLVED","current_status":"CURRENT","collection_complete":true}','{"synthetic":true}',null,null,'c9000000-0000-4000-8000-000000000110');
insert into w3 select 'flow_extra',evidence_version_id from public.create_synthetic_research_evidence((select value from w3 where key='enrollment'),(select value from w3 where key='evaluation'),'FSH','c1000000-0000-4000-8000-000000000001','PUR-01','FSH-FLOW-EXTRA','SYSTEM_RECORDED','2026-08-01','2026-08-01','PRESENT','{"value":10.0000,"operand_identity":"FSH-OP-FLOW-CURRENT-AMOUNT-v0.1","canonical_membership_identity":"FLOW-B","currency":"INR","unit":"MONTHLY_CURRENCY_AMOUNT","period_start":"2026-08-01","period_end":"2026-08-31","mechanics_state":"ELIGIBLE","authority_state":"RESOLVED","current_status":"CURRENT","collection_complete":true}','{"synthetic":true}',null,null,'c9000000-0000-4000-8000-000000000111');
insert into w3 select 'load_zero',evidence_version_id from public.create_synthetic_research_evidence((select value from w3 where key='enrollment'),(select value from w3 where key='evaluation'),'FSH','c1000000-0000-4000-8000-000000000001','PUR-01','FSH-LOAD-ZERO','SYSTEM_RECORDED','2026-08-01','2026-08-01','CONFIRMED_ZERO','{"value":0.0000,"operand_identity":"FSH-OP-LOAD-CURRENT-AMOUNT-v0.1","canonical_membership_identity":"LOAD-ZERO","currency":"INR","unit":"MONTHLY_CURRENCY_AMOUNT","period_start":"2026-08-01","period_end":"2026-08-31","mechanics_state":"ELIGIBLE","authority_state":"RESOLVED","current_status":"CURRENT","collection_complete":true}','{"synthetic":true}',null,null,'c9000000-0000-4000-8000-000000000112');
insert into w3 select 'flow_zero',evidence_version_id from public.create_synthetic_research_evidence((select value from w3 where key='enrollment'),(select value from w3 where key='evaluation'),'FSH','c1000000-0000-4000-8000-000000000001','PUR-01','FSH-FLOW-ZERO','SYSTEM_RECORDED','2026-08-01','2026-08-01','CONFIRMED_ZERO','{"value":0.0000,"operand_identity":"FSH-OP-FLOW-CURRENT-AMOUNT-v0.1","canonical_membership_identity":"FLOW-ZERO","currency":"INR","unit":"MONTHLY_CURRENCY_AMOUNT","period_start":"2026-08-01","period_end":"2026-08-31","mechanics_state":"ELIGIBLE","authority_state":"RESOLVED","current_status":"CURRENT","collection_complete":true}','{"synthetic":true}',null,null,'c9000000-0000-4000-8000-000000000113');
insert into w3 values('snapshot2',public.freeze_synthetic_research_snapshot((select value from w3 where key='enrollment'),'FSH','c1000000-0000-4000-8000-000000000001','BASELINE',(select value from w3 where key='snapshot1'),array[(select value from w3 where key='load2'),(select value from w3 where key='flow2'),(select value from w3 where key='load_extra'),(select value from w3 where key='flow_extra'),(select value from w3 where key='load_zero'),(select value from w3 where key='flow_zero')],'COMPLETE','CURRENT','c9000000-0000-4000-8000-000000000012'));
create temporary table fsh2 as select * from public.execute_synthetic_governed_fsh((select value from w3 where key='snapshot2'),'c1000000-0000-4000-8000-000000000001','{"capacity_qualification":"ELIGIBLE_METADATA_ONLY"}','c9000000-0000-4000-8000-000000000013');
insert into w3 select 'result2',result_id from fsh2;
select is((select load_total from fsh2),'130.2500','multiple LOAD records sum exactly and confirmed zero is preserved');
select is((select flow_total from fsh2),'150.7500','multiple FLOW records sum exactly and confirmed zero is preserved');
select is((select fsh_value from fsh2),'20.5000','successor multi-record calculation is exact');
select is((select count(*) from public.research_fsh_collection_members m join public.research_fsh_collections c on c.id=m.collection_id where c.snapshot_id=(select value from w3 where key='snapshot2') and m.value_state='CONFIRMED_ZERO'),2::bigint,'confirmed-zero LOAD and FLOW contributions remain explicit members');
select is((select count(distinct m.ordinal) from public.research_fsh_collection_members m join public.research_fsh_collections c on c.id=m.collection_id where c.snapshot_id=(select value from w3 where key='snapshot2') and c.collection_family='FLOW'),3::bigint,'multiple FLOW members receive deterministic unique ordinals');
select is((select predecessor_result_id from public.research_fsh_results where id=(select value from w3 where key='result2')),(select value from w3 where key='result1'),'successor result links predecessor');
select is((select current_status from public.research_fsh_result_status where id=(select value from w3 where key='result1')),'SUPERSEDED','prior result status is derived as superseded');
select is((select current_status from public.research_fsh_result_status where id=(select value from w3 where key='result2')),'CURRENT','successor result is current');
select is((select count(*) from public.research_fsh_result_supersession_events),1::bigint,'supersession is append-only event');
select throws_ok(format($q$select * from public.execute_synthetic_governed_fsh(%L,'c1000000-0000-4000-8000-000000000001','{}','c9000000-0000-4000-8000-000000000014')$q$,(select value from w3 where key='snapshot1')),'P1001','FSH requires the current complete frozen FSH snapshot.','stale predecessor snapshot is blocked');

-- Incident invalid paths, gates, restoration, closure, and successor identity.
insert into w3 values('incident',public.report_research_incident((select value from w3 where key='enrollment'),'c1000000-0000-4000-8000-000000000001','INC-FAM-07','SYNTHETIC_EVIDENCE_INTEGRITY',null,'UNKNOWN','FSH-EVIDENCE-SCOPE','[]',array['EVIDENCE_USE','FSH_EXECUTION'],'PROTECTIVE_HOLD_REQUIRED',true,'c9000000-0000-4000-8000-000000000020'));
select is(public.current_research_incident_status((select value from w3 where key='incident')),'REPORTED','new Incident starts REPORTED');
create temporary table invalid_transition as select * from public.transition_research_incident((select value from w3 where key='incident'),'c1000000-0000-4000-8000-000000000002','RESOLVED','{}','{}','c9000000-0000-4000-8000-000000000021');
select is((select transition_applied from invalid_transition),false,'invalid transition does not apply');
select is((select technical_result from invalid_transition),'INCIDENT_TRANSITION_INVALID','invalid transition returns canonical technical result');
select is(public.current_research_incident_status((select value from w3 where key='incident')),'REPORTED','invalid transition preserves status');
select is(public.current_research_incident_gate((select value from w3 where key='incident'),'FSH_EXECUTION'),'BLOCKED','invalid transition preserves gate posture');
select is((select count(*) from public.research_control_audit_events where event_type='INCIDENT_TRANSITION_INVALID' and metadata->>'incident_id'=(select value::text from w3 where key='incident')),1::bigint,'invalid transition emits Audit event');
select throws_ok(format($q$select public.assert_wave3_incident_gate(%L,'FSH_EXECUTION')$q$,(select value from w3 where key='enrollment')),'P1001','A material unresolved Incident blocks this research operation.','material Incident blocks FSH gate');
select lives_ok(format($q$select * from public.transition_research_incident(%L,'c1000000-0000-4000-8000-000000000002','TRIAGE_REQUIRED','{}','{}','c9000000-0000-4000-8000-000000000022')$q$,(select value from w3 where key='incident')),'valid REPORTED to TRIAGE_REQUIRED transition');
select lives_ok(format($q$select * from public.transition_research_incident(%L,'c1000000-0000-4000-8000-000000000002','REVIEW_REQUIRED',array['INC-PRE-01','INC-PRE-02'],'{}','c9000000-0000-4000-8000-000000000023')$q$,(select value from w3 where key='incident')),'triage may hand off to governed review');
select throws_ok(format($q$select * from public.transition_research_incident(%L,'c1000000-0000-4000-8000-000000000001','RESOLVED',array['INC-PRE-04','INC-PRE-05','INC-PRE-06','INC-PRE-07','INC-PRE-08','INC-PRE-09','INC-PRE-10'],'{}','c9000000-0000-4000-8000-000000000024')$q$,(select value from w3 where key='incident')),'P1001','Incident reviewer independence is invalid.','reporter cannot resolve Incident');
select lives_ok(format($q$select * from public.transition_research_incident(%L,'c1000000-0000-4000-8000-000000000003','RESOLVED',array['INC-PRE-04','INC-PRE-05','INC-PRE-06','INC-PRE-07','INC-PRE-08','INC-PRE-09','INC-PRE-10'],'{}','c9000000-0000-4000-8000-000000000025')$q$,(select value from w3 where key='incident')),'independent reviewer resolves Incident');
select is(public.current_research_incident_gate((select value from w3 where key='incident'),'FSH_EXECUTION'),'BLOCKED','RESOLVED does not restore gate');
select throws_ok(format($q$select public.restore_research_incident_gate(%L,'FSH_EXECUTION','c1000000-0000-4000-8000-000000000002','{"authority":"RECOVERY-v1","evidence":"SYNTHETIC-CORRECTION","independent_reviewer":"c1000000-0000-4000-8000-000000000002"}','GOVERNED_RECOVERY','c9000000-0000-4000-8000-000000000126')$q$,(select value from w3 where key='incident')),'P1001','Incident gate restoration prerequisites are not satisfied.','restoring actor cannot self-attest as independent reviewer');
select lives_ok(format($q$select public.restore_research_incident_gate(%L,'FSH_EXECUTION','c1000000-0000-4000-8000-000000000002','{"authority":"RECOVERY-v1","evidence":"SYNTHETIC-CORRECTION","independent_reviewer":"c1000000-0000-4000-8000-000000000003"}','GOVERNED_RECOVERY','c9000000-0000-4000-8000-000000000026')$q$,(select value from w3 where key='incident')),'separate governed restoration opens only affected gate');
select is(public.current_research_incident_gate((select value from w3 where key='incident'),'FSH_EXECUTION'),'OPEN','governed restoration event is current');
select is(public.current_research_incident_gate((select value from w3 where key='incident'),'EVIDENCE_USE'),'BLOCKED','other gate remains blocked');
select throws_ok(format($q$select * from public.transition_research_incident(%L,'c1000000-0000-4000-8000-000000000003','CLOSED',array['INC-PRE-08','INC-PRE-09','INC-PRE-10','INC-PRE-11'],'{}','c9000000-0000-4000-8000-000000000027')$q$,(select value from w3 where key='incident')),'P1001','Incident closure independence is invalid.','resolver cannot also close');
select lives_ok(format($q$select * from public.transition_research_incident(%L,'c1000000-0000-4000-8000-000000000002','CLOSED',array['INC-PRE-08','INC-PRE-09','INC-PRE-10','INC-PRE-11'],'{}','c9000000-0000-4000-8000-000000000028')$q$,(select value from w3 where key='incident')),'independent closure is allowed');
select is(public.current_research_incident_status((select value from w3 where key='incident')),'CLOSED','Incident reaches immutable CLOSED');
insert into w3 values('successor_incident',public.create_successor_research_incident((select value from w3 where key='incident'),'c1000000-0000-4000-8000-000000000002',true,null,'[{"new":"synthetic_evidence"}]','c9000000-0000-4000-8000-000000000029'));
select is((select predecessor_incident_id from public.research_incidents where id=(select value from w3 where key='successor_incident')),(select value from w3 where key='incident'),'material new evidence creates successor Incident identity');
select is(public.current_research_incident_status((select value from w3 where key='incident')),'CLOSED','successor never mutates closed predecessor');
select is(public.current_research_incident_status((select value from w3 where key='successor_incident')),'REPORTED','successor starts REPORTED');
select throws_ok(format($q$update public.research_incidents set affected_scope='MUTATED' where id=%L$q$,(select value from w3 where key='incident')),'P1001','Research Wave 3 records are append-only.','Incident root is immutable');

-- Audit completeness and loop guard.
create temporary table audit_check as select * from public.assess_research_audit_completeness((select value from w3 where key='enrollment'),null,'SYNTHETIC-AUDIT-SCOPE',array['EVENT_THAT_IS_MISSING'],'c1000000-0000-4000-8000-000000000002',true,'c9000000-0000-4000-8000-000000000030');
select is((select integrity_status from audit_check),'AUDIT_INTEGRITY_UNRESOLVED','missing mandatory history is explicit unresolved Audit posture');
select isnt((select incident_candidate_id from audit_check),null::uuid,'Audit integrity failure creates distinct Incident candidate');
select lives_ok(format($q$select * from public.assess_research_audit_completeness(%L,null,'SYNTHETIC-AUDIT-SCOPE',array['EVENT_THAT_IS_MISSING'],'c1000000-0000-4000-8000-000000000002',true,'c9000000-0000-4000-8000-000000000030')$q$,(select value from w3 where key='enrollment')),'repeated assessment does not recurse');
select is((select count(*) from public.research_incidents where correlation_id='c9000000-0000-4000-8000-000000000030'),1::bigint,'Audit to Incident candidate is deduplicated');
select throws_ok('update public.research_control_audit_events set reason_code=''MUTATED'' where event_type=''GOVERNED_FSH_EXECUTED''','P1001','Research control history is append-only.','unified Audit remains immutable');

-- Release gate is physically fail-closed.
create temporary table release_check as select * from public.evaluate_wave3_release_gate('synthetic_test','c1000000-0000-4000-8000-000000000001','c9000000-0000-4000-8000-000000000040');
select is((select gate_status from release_check),'BLOCKED','B1 blockers keep release blocked');
select ok((select reason_codes @> array['CONSENT_WORDING_PENDING_INDEPENDENT_REVIEW'] from release_check),'unapproved participant consent wording blocks release');
select ok((select reason_codes @> array['LEGAL_PRIVACY_DEPENDENCY_UNRESOLVED'] from release_check),'legal/privacy dependency remains unresolved');
select is((select dependency_results->>'synthetic_e2e' from public.research_release_gate_assessments where id=(select assessment_id from release_check)),'IMPLEMENTED_PENDING_INDEPENDENT_VERIFICATION','synthetic E2E remains subject to independent verification');
select is((select dependency_results->>'participant_output_suppression' from public.research_release_gate_assessments where id=(select assessment_id from release_check)),'OPEN','participant output suppression check is satisfied');
select is((select dependency_results->>'actual_enrollment' from public.research_release_gate_assessments where id=(select assessment_id from release_check)),'NOT_AUTHORIZED','real enrollment attempt remains rejected');
select is((select dependency_results->>'evidence_collection' from public.research_release_gate_assessments where id=(select assessment_id from release_check)),'NOT_AUTHORIZED','real evidence activation remains rejected');
select is((select dependency_results->>'pilot' from public.research_release_gate_assessments where id=(select assessment_id from release_check)),'NOT_AUTHORIZED','Pilot activation remains rejected');
select is((select count(*) from public.research_release_gate_assessments where gate_status not in ('BLOCKED','UNRESOLVED')),0::bigint,'Wave 3 physical release domain cannot contain OPEN');
select ok((select bool_and(actual_enrollment_status in ('BLOCKED','NOT_AUTHORIZED') and evidence_collection_status in ('BLOCKED','NOT_AUTHORIZED') and pilot_status='NOT_AUTHORIZED' and production_status='NOT_AUTHORIZED') from public.research_release_firewall),'Wave 1 firewall remains intact');

select * from finish();
rollback;
